"""Ledger entries and the parser for the plain-text ledger format."""

import datetime
import re
from dataclasses import dataclass
from decimal import Decimal, localcontext

_DATE_RE = re.compile(r"\d{4}-\d{2}-\d{2}", re.ASCII)
_AMOUNT_RE = re.compile(r"[+-]?\d+(\.\d{1,2})?", re.ASCII)
_SEPARATOR_RE = re.compile(r"[ \t]+")
_TWO_PLACES = Decimal("0.01")


@dataclass(frozen=True)
class Entry:
    """One ledger line."""

    date: datetime.date
    category: str
    amount: Decimal
    note: str = ""


class ParseError(ValueError):
    """A line of the ledger is not valid. ``line`` is its 1-based number."""

    def __init__(self, line, message):
        super().__init__("line %d: %s" % (line, message))
        self.line = line
        self.message = message

    def __reduce__(self):
        return (type(self), (self.line, self.message))


def _parse_date(text):
    if not _DATE_RE.fullmatch(text):
        raise ValueError("invalid date %r (expected YYYY-MM-DD)" % text)
    try:
        return datetime.date(int(text[0:4]), int(text[5:7]), int(text[8:10]))
    except ValueError:
        raise ValueError("invalid date %r (no such day)" % text) from None


def _parse_amount(text):
    if not _AMOUNT_RE.fullmatch(text):
        raise ValueError(
            "invalid amount %r (expected a number with at most two decimals)" % text
        )
    return Decimal(text)


def parse(text):
    """Parse ledger text into a list of :class:`Entry`, in file order.

    Raises :class:`ParseError` for the first bad line.
    """
    entries = []
    lines = text.replace("\r\n", "\n").replace("\r", "\n").split("\n")
    for number, raw in enumerate(lines, start=1):
        stripped = raw.strip()
        if not stripped or stripped.startswith("#"):
            continue
        fields = _SEPARATOR_RE.split(stripped, maxsplit=3)
        if len(fields) < 3:
            raise ParseError(
                number, "expected DATE CATEGORY AMOUNT [NOTE], got %d field(s)" % len(fields)
            )
        try:
            date = _parse_date(fields[0])
            amount = _parse_amount(fields[2])
        except ValueError as exc:
            raise ParseError(number, str(exc)) from None
        note = fields[3] if len(fields) > 3 else ""
        entries.append(Entry(date, fields[1].lower(), amount, note))
    return entries


def format_amount(amount):
    """Format a Decimal with exactly two decimals (negative zero prints as 0.00)."""
    with localcontext() as ctx:
        ctx.prec = max(ctx.prec, amount.adjusted() + 6) if amount.is_finite() else ctx.prec
        quantized = amount.quantize(_TWO_PLACES)
    if quantized == 0:
        quantized = abs(quantized)
    return format(quantized, "f")


def format_entry(entry):
    """Format an entry as ``DATE CATEGORY AMOUNT[ NOTE]``."""
    line = "%s %s %s" % (entry.date.isoformat(), entry.category, format_amount(entry.amount))
    if entry.note:
        line += " " + entry.note
    return line
"""Totals and filtering over parsed entries."""

from decimal import Decimal


def balance(entries):
    """Total of all amounts as a Decimal (zero for no entries)."""
    total = Decimal(0)
    for entry in entries:
        total += entry.amount
    return total


def _group(entries, key):
    totals = {}
    for entry in entries:
        k = key(entry)
        totals[k] = totals.get(k, Decimal(0)) + entry.amount
    return {k: totals[k] for k in sorted(totals)}


def by_category(entries):
    """dict of category -> total, keys sorted."""
    return _group(entries, lambda e: e.category)


def by_month(entries):
    """dict of ``"YYYY-MM"`` -> total, keys sorted."""
    return _group(entries, lambda e: "%04d-%02d" % (e.date.year, e.date.month))


def filter_entries(entries, category=None, since=None, until=None):
    """Matching entries in input order. ``None`` means no filter; bounds are inclusive."""
    if category is not None:
        category = category.lower()
    result = []
    for entry in entries:
        if category is not None and entry.category != category:
            continue
        if since is not None and entry.date < since:
            continue
        if until is not None and entry.date > until:
            continue
        result.append(entry)
    return result
"""The ``pennywise`` command line."""

import argparse
import csv
import datetime
import io
import json
import re
import sys

from .ledger import ParseError, format_amount, format_entry, parse
from .report import balance, by_category, by_month, filter_entries

_CLI_DATE_RE = re.compile(r"\d{4}-\d{2}-\d{2}", re.ASCII)


class _ReadError(Exception):
    """The ledger could not be read (exit 2)."""


def _date_arg(text):
    if _CLI_DATE_RE.fullmatch(text):
        try:
            return datetime.date(int(text[0:4]), int(text[5:7]), int(text[8:10]))
        except ValueError:
            pass
    raise argparse.ArgumentTypeError("invalid date %r (expected YYYY-MM-DD)" % text)


def _build_parser():
    parser = argparse.ArgumentParser(
        prog="pennywise", description="Report where the money went from a plain-text ledger."
    )
    sub = parser.add_subparsers(dest="command", metavar="COMMAND")
    sub.required = True

    def add_file(p):
        p.add_argument("file", metavar="FILE", help="ledger file, or - for standard input")

    p = sub.add_parser("balance", help="print the total of all entries")
    add_file(p)
    p.add_argument("--json", action="store_true", help="print JSON")

    p = sub.add_parser("summary", help="print totals per category or month")
    add_file(p)
    p.add_argument("--by", choices=["category", "month"], default="category")
    p.add_argument("--json", action="store_true", help="print JSON")

    p = sub.add_parser("list", help="print entries, oldest first")
    add_file(p)
    p.add_argument("--category", help="only this category (any case)")
    p.add_argument("--since", type=_date_arg, metavar="DATE", help="first day, YYYY-MM-DD")
    p.add_argument("--until", type=_date_arg, metavar="DATE", help="last day, YYYY-MM-DD")
    p.add_argument("--json", action="store_true", help="print JSON")

    p = sub.add_parser("add", help="append an entry to the ledger file")
    p.add_argument("file", metavar="FILE", help="ledger file (created if missing)")
    p.add_argument("date", metavar="DATE")
    p.add_argument("category", metavar="CATEGORY")
    p.add_argument("amount", metavar="AMOUNT")
    p.add_argument("note", metavar="NOTE", nargs="?", default="")

    p = sub.add_parser("export", help="print entries as CSV")
    add_file(p)
    p.add_argument("--format", choices=["csv"], default="csv")

    return parser


def _read_ledger(path):
    try:
        if path == "-":
            return sys.stdin.read()
        with open(path, "rb") as handle:
            return handle.read().decode("utf-8-sig")
    except (OSError, UnicodeDecodeError) as exc:
        raise _ReadError("cannot read %s: %s" % ("standard input" if path == "-" else path, exc))


def _sorted_entries(args, entries):
    chosen = filter_entries(entries, args.category, args.since, args.until)
    return sorted(chosen, key=lambda e: e.date)


def _out(text):
    sys.stdout.write(text + "\n")


def _cmd_balance(args, entries):
    total = format_amount(balance(entries))
    _out(json.dumps({"balance": total}) if args.json else total)


def _cmd_summary(args, entries):
    totals = (by_month if args.by == "month" else by_category)(entries)
    formatted = {name: format_amount(total) for name, total in sorted(totals.items())}
    if args.json:
        _out(json.dumps(formatted))
    else:
        for name, total in formatted.items():
            _out("%s  %s" % (name, total))


def _cmd_list(args, entries):
    chosen = _sorted_entries(args, entries)
    if args.json:
        _out(
            json.dumps(
                [
                    {
                        "date": e.date.isoformat(),
                        "category": e.category,
                        "amount": format_amount(e.amount),
                        "note": e.note,
                    }
                    for e in chosen
                ]
            )
        )
    else:
        for entry in chosen:
            _out(format_entry(entry))


def _cmd_export(args, entries):
    buffer = io.StringIO()
    writer = csv.writer(buffer, lineterminator="\n")
    writer.writerow(["date", "category", "amount", "note"])
    for e in sorted(entries, key=lambda e: e.date):
        writer.writerow([e.date.isoformat(), e.category, format_amount(e.amount), e.note])
    sys.stdout.write(buffer.getvalue())


_READERS = {
    "balance": _cmd_balance,
    "summary": _cmd_summary,
    "list": _cmd_list,
    "export": _cmd_export,
}


def _cmd_add(args):
    """Validate and append one entry. Returns an exit status."""
    if args.file == "-":
        print("pennywise: add cannot write to standard input", file=sys.stderr)
        return 2
    note = args.note
    try:
        for name, value in (("date", args.date), ("category", args.category), ("amount", args.amount)):
            if not value or re.search(r"\s", value):
                raise ParseError(1, "invalid %s %r" % (name, value))
        if "\n" in note or "\r" in note:
            raise ParseError(1, "note must not contain a newline")
        entries = parse("%s %s %s %s" % (args.date, args.category, args.amount, note))
    except ParseError as exc:
        print("pennywise: %s" % exc, file=sys.stderr)
        return 1
    line = format_entry(entries[0])

    try:
        with open(args.file, "ab+") as handle:
            handle.seek(0, 2)
            prefix = b""
            if handle.tell() > 0:
                handle.seek(-1, 2)
                if handle.read(1) != b"\n":
                    prefix = b"\n"
            handle.write(prefix + (line + "\n").encode("utf-8"))
    except OSError as exc:
        print("pennywise: cannot write %s: %s" % (args.file, exc), file=sys.stderr)
        return 2
    _out(line)
    return 0


def _run(args):
    if args.command == "add":
        return _cmd_add(args)
    try:
        text = _read_ledger(args.file)
    except _ReadError as exc:
        print("pennywise: %s" % exc, file=sys.stderr)
        return 2
    try:
        entries = parse(text)
    except ParseError as exc:
        print("pennywise: %s" % exc, file=sys.stderr)
        return 1
    _READERS[args.command](args, entries)
    return 0


def main(argv=None):
    """Run the command line; returns the exit status."""
    try:
        args = _build_parser().parse_args(argv)
    except SystemExit as exc:
        code = exc.code
        return code if isinstance(code, int) else (0 if code is None else 2)
    return _run(args)
