"""Slow check: `pip install .` into a throwaway venv gives the library and the command."""

import os
import shutil
import subprocess
import sys
import tempfile
import unittest
import venv

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
SAMPLE = "2024-03-01 salary 2500.00 March pay\n2024-03-02 groceries -42.50 weekly shop\n"


class PackagingTests(unittest.TestCase):
    def test_pip_install_gives_library_and_command(self):
        with tempfile.TemporaryDirectory() as tmp:
            src = os.path.join(tmp, "project")
            shutil.copytree(
                ROOT, src,
                ignore=shutil.ignore_patterns(".git", ".claude", "__pycache__", "build",
                                              "*.egg-info", ".venv"),
            )
            env_dir = os.path.join(tmp, "venv")
            venv.EnvBuilder(with_pip=False, system_site_packages=False).create(env_dir)
            bindir = "Scripts" if os.name == "nt" else "bin"
            py = os.path.join(env_dir, bindir, "python")
            exe = os.path.join(env_dir, bindir, "pennywise" + (".exe" if os.name == "nt" else ""))
            proc = subprocess.run([sys.executable, "-m", "pip", "--python", py, "install", "--no-input", "."],
                                  cwd=src, capture_output=True, text=True)
            if proc.returncode != 0:
                # Offline hosts cannot fetch the isolated build requirement; reuse local setuptools.
                proc = subprocess.run(
                    [sys.executable, "-m", "pip", "--python", py, "install", "--no-input",
                     "--no-build-isolation", "."],
                    cwd=src, capture_output=True, text=True)
            if proc.returncode != 0:
                self.skipTest("pip install unavailable here:\n" + proc.stdout[-1500:] + proc.stderr[-1500:])

            neutral = os.path.join(tmp, "elsewhere")
            os.mkdir(neutral)
            ledger = os.path.join(neutral, "house.txt")
            with open(ledger, "w") as f:
                f.write(SAMPLE)
            code = subprocess.run(
                [py, "-c", "import pennywise, sys; "
                           "print(pennywise.balance(pennywise.parse(open(sys.argv[1]).read())))", ledger],
                cwd=neutral, capture_output=True, text=True)
            self.assertEqual((code.returncode, code.stdout.strip()), (0, "2457.50"), code.stderr)
            cmd = subprocess.run([exe, "balance", ledger], cwd=neutral, capture_output=True, text=True)
            self.assertEqual((cmd.returncode, cmd.stdout), (0, "2457.50\n"), cmd.stderr)
            shown = subprocess.run([sys.executable, "-m", "pip", "--python", py, "show", "pennywise"],
                                   capture_output=True, text=True).stdout
            self.assertIn("Requires: \n", shown)


if __name__ == "__main__":
    unittest.main()

